package org.apache.commons.math.fraction;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.exception.MathIllegalArgumentException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.ZeroException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.ArithmeticUtils;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for {@link BigFraction#doubleValue()}
 */
public class BigFraction_doubleValue_TriageGen2Test {

    private static final double EPSILON = 1e-12;

    @Test
    public void testDoubleValueWithSimpleIntegers() {
        BigFraction fraction = new BigFraction(1, 2);
        assertEquals(0.5, fraction.doubleValue(), EPSILON);
    }

    @Test
    public void testDoubleValueWithNegativeNumerator() {
        BigFraction fraction = new BigFraction(-3, 4);
        assertEquals(-0.75, fraction.doubleValue(), EPSILON);
    }

    @Test
    public void testDoubleValueWithNegativeDenominator() {
        BigFraction fraction = new BigFraction(5, -10);
        assertEquals(-0.5, fraction.doubleValue(), EPSILON);
    }

    @Test
    public void testDoubleValueWithBothNegative() {
        BigFraction fraction = new BigFraction(-1, -4);
        assertEquals(0.25, fraction.doubleValue(), EPSILON);
    }

    @Test
    public void testDoubleValueWithZeroNumerator() {
        BigFraction fraction = new BigFraction(0, 5);
        assertEquals(0.0, fraction.doubleValue(), EPSILON);
    }

    @Test
    public void testDoubleValueWithLargeValues() {
        // Testing precision and large BigInteger conversion to double
        BigInteger num = new BigInteger("12345678901234567890");
        BigInteger den = new BigInteger("2");
        BigFraction fraction = new BigFraction(num, den);

        double expected = num.doubleValue() / den.doubleValue();
        assertEquals(expected, fraction.doubleValue(), EPSILON);
    }

    @Test
    public void testDoubleValueResultingInInfinity() {
        // BigFraction doesn't allow zero denominator in constructor, 
        // but we test the behavior of the division logic if it were to result in infinity
        // via large values or specific math properties.
        // Since we can't easily create a 0 denominator BigFraction, 
        // we use extremely large values that might approach infinity.
        BigFraction fraction = new BigFraction(Long.MAX_VALUE, 1L);
        assertEquals((double) Long.MAX_VALUE, fraction.doubleValue(), EPSILON);
    }

    @Test
    public void testDoubleValueWithSmallFraction() {
        BigFraction fraction = new BigFraction(1, 1000000);
        assertEquals(0.000001, fraction.doubleValue(), EPSILON);
    }

    @Test
    public void testDoubleValueWithDecimalConstructor() {
        BigFraction fraction = new BigFraction(0.125);
        assertEquals(0.125, fraction.doubleValue(), EPSILON);
    }

    @Test
    public void testDoubleValueWithLargeDenominator() {
        BigInteger num = BigInteger.ONE;
        BigInteger den = new BigInteger("1000000000000000000000000000000");
        BigFraction fraction = new BigFraction(num, den);
        assertEquals(1.0 / den.doubleValue(), fraction.doubleValue(), EPSILON);
    }
}
